[CmdletBinding()]
param([string]$StateDirectory='C:\CodexRuntime\operator\admin\skincos\observability',[int]$Port=18799)
$ErrorActionPreference='Stop'; $prefix="http://127.0.0.1:$Port/"; $listener=New-Object System.Net.HttpListener; $listener.Prefixes.Add($prefix); $listener.Start()
try { while($listener.IsListening) { $context=$listener.GetContext(); $path=$context.Request.Url.AbsolutePath; $file=if($path -eq '/metrics'){Join-Path $StateDirectory 'metrics.prom'}elseif($path -eq '/health'){Join-Path $StateDirectory 'monitor-health.json'}else{Join-Path $StateDirectory 'dashboard.html'}; $body=if(Test-Path $file){[System.IO.File]::ReadAllText($file)}else{'{"ok":false,"error":"MONITOR_STATE_UNAVAILABLE"}'}; $health=$path -eq '/health' -and $body -match '"ok"\s*:\s*true'; $context.Response.StatusCode=if($path -eq '/health' -and -not $health){503}else{200}; $context.Response.ContentType=if($path -eq '/metrics'){'text/plain; version=0.0.4'}elseif($path -eq '/health'){'application/json'}else{'text/html; charset=utf-8'}; $bytes=[Text.Encoding]::UTF8.GetBytes($body); $context.Response.OutputStream.Write($bytes,0,$bytes.Length); $context.Response.Close() } } finally { $listener.Stop(); $listener.Close() }
